contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address probe) public {
        require(probe != address(this));
        uint probeBefore = c.balances(probe); if (__ESBMC_reverted()) return;
        c.withdraw(); if (__ESBMC_reverted()) return;
        uint probeMid = c.balances(probe); if (__ESBMC_reverted()) return;
        uint selfMid = c.balances(address(this)); if (__ESBMC_reverted()) return;
        c.withdraw(); if (__ESBMC_reverted()) return;
        assert(
            probeMid == probeBefore &&
            selfMid == 0 &&
            c.balances(probe) == probeBefore &&
            c.balances(address(this)) == 0
        );
    }
    receive() external payable {}
}

