pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    keepMyEther c;

    function setUp() public {
        c = new keepMyEther();
    }

    function _run(address probe) internal {
        vm.assume(probe != address(this));
        uint256 probeBefore;
        try c.balances(probe) returns (uint256 __r) { probeBefore = __r; } catch { return; }
        try c.withdraw() {} catch { return; }
        uint256 probeMid;
        try c.balances(probe) returns (uint256 __r) { probeMid = __r; } catch { return; }
        uint256 selfMid;
        try c.balances(address(this)) returns (uint256 __r) { selfMid = __r; } catch { return; }
        try c.withdraw() {} catch { return; }
        assertTrue(probeMid == probeBefore &&
            selfMid == 0 &&
            c.balances(probe) == probeBefore &&
            c.balances(address(this)) == 0);
    }

    function testFuzz_run(address probe) public {
        vm.assume(probe.code.length == 0 && uint160(probe) > 0xffff && probe != address(this) && probe != address(c) && probe != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && probe != 0x000000000000000000636F6e736F6c652e6c6f67 && probe != 0x4e59b44847b379578588920cA78FbF26c0B4956C && probe != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(probe);
    }

    receive() external payable {}
}
